+// Component-based initialization pattern
+class EcommerceApp {
+    constructor() {
+        this.cart = {
+            items: 0,
+            products: []
+        };
+        this.init();
+    }
+
+    init() {
+        this.setupEventListeners();
+        this.loadCartState();
+        this.setupProductInteractions();
+    }
+
+    setupEventListeners() {
+        // Newsletter form
+        const newsletterForm = document.getElementById('newsletter-form');
+        if (newsletterForm) {
+            newsletterForm.addEventListener('submit', (e) => this.handleNewsletterSubmit(e));
+        }
+
+        // Product cards - add to cart on click
+        this.setupProductCards();
+
+        // Navigation links
+        this.setupNavigation();
+    }
+
+    setupProductCards() {
+        const productCards = document.querySelectorAll('.product-card');
+        productCards.forEach((card, index) => {
+            card.style.cursor = 'pointer';
+            card.addEventListener('click', () => this.handleProductClick(card, index));
+        });
+    }
+
+    handleProductClick(card, index) {
+        const productName = card.querySelector('.product-name').textContent;
+        const productPrice = card.querySelector('.price').textContent;
+        
+        // Add to cart
+        this.addToCart({
+            id: index,
+            name: productName,
+            price: productPrice
+        });
+
+        // Show feedback
+        this.showFeedback(`${productName} added to cart!`);
+    }
+
+    setupProductInteractions() {
+        // Deal cards interaction
+        const dealCards = document.querySelectorAll('.deal-card');
+        dealCards.forEach(card => {
+            const button = card.querySelector('.cta-button');
+            if (button) {
+                button.addEventListener('click', (e) => {
+                    e.stopPropagation();
+                    const dealTitle = card.querySelector('.deal-title').textContent;
+                    this.showFeedback(`Viewing ${dealTitle}...`);
+                });
+            }
+        });
+
+        // Article links
+        const articleLinks = document.querySelectorAll('.article-link');
+        articleLinks.forEach(link => {
+            link.addEventListener('click', (e) => {
+                e.preventDefault();
+                const articleTitle = link.closest('.article-card')
+                    .querySelector('.article-title').textContent;
+                this.showFeedback(`Reading: ${articleTitle}`);
+            });
+        });
+
+        // CTA buttons
+        const ctaButtons = document.querySelectorAll('.cta-button');
+        ctaButtons.forEach(btn => {
+            btn.addEventListener('click', (e) => {
+                if (btn.closest('.hero')) {
+                    e.preventDefault();
+                    this.showFeedback('Browsing collection...');
+                }
+            });
+        });
+    }
+
+    setupNavigation() {
+        const navLinks = document.querySelectorAll('.nav-link');
+        navLinks.forEach(link => {
+            link.addEventListener('click', (e) => {
+                e.preventDefault();
+                const text = link.textContent;
+                this.showFeedback(`Navigating to ${text}...`);
+            });
+        });
+    }
+
+    addToCart(product) {
+        this.cart.items++;
+        this.cart.products.push(product);
+        this.updateCartUI();
+        this.saveCartState();
+    }
+
+    updateCartUI() {
+        const cartCount = document.querySelector('.cart-count');
+        if (cartCount) {
+            cartCount.textContent = this.cart.items;
+        }
+    }
+
+    saveCartState() {
+        try {
+            localStorage.setItem('cart', JSON.stringify(this.cart));
+        } catch (e) {
+            console.warn('LocalStorage not available');
+        }
+    }
+
+    loadCartState() {
+        try {
+            const saved = localStorage.getItem('cart');
+            if (saved) {
+                this.cart = JSON.parse(saved);
+                this.updateCartUI();
+            }
+        } catch (e) {
+            console.warn('Could not load cart state');
+        }
+    }
+
+    handleNewsletterSubmit(e) {
+        e.preventDefault();
+        const form = e.target;
+        const email = form.querySelector('input[type="email"]').value;
+        
+        if (email) {
+            this.showFeedback(`Welcome! Check ${email} for exclusive offers.`, 'success');
+            form.reset();
+        }
+    }
+
+    showFeedback(message, type = 'info') {
+        // Create feedback element
+        const feedback = document.createElement('div');
+        feedback.className = `feedback feedback-${type}`;
+        feedback.textContent = message;
+        feedback.style.cssText = `
+            position: fixed;
+            bottom: 20px;
+            right: 20px;
+            background: ${type === 'success' ? '#10b981' : '#3b82f6'};
